// api100cDelE returns raw with the key at each dotted path deleted (a number selects an array element). It fails
// if a path does not exist, so a stale path cannot hide an unmodelled key.
func api100cDelE(raw string, paths ...string) ([]byte, error) {
	var root any
	if err := json.Unmarshal([]byte(raw), &root); err != nil {
		return nil, err
	}
	for _, p := range paths {
		parts := strings.Split(p, ".")
		v := root
		for _, k := range parts[:len(parts)-1] {
			switch c := v.(type) {
			case map[string]any:
				var ok bool
				if v, ok = c[k]; !ok {
					return nil, fmt.Errorf("path %q: no key %q", p, k)
				}
			case []any:
				i, err := strconv.Atoi(k)
				if err != nil || i < 0 || i >= len(c) {
					return nil, fmt.Errorf("path %q: no element %q", p, k)
				}
				v = c[i]
			default:
				return nil, fmt.Errorf("path %q: %q is not in an object or array", p, k)
			}
		}
		m, ok := v.(map[string]any)
		last := parts[len(parts)-1]
		if !ok {
			return nil, fmt.Errorf("path %q: not an object before %q", p, last)
		}
		if _, ok := m[last]; !ok {
			return nil, fmt.Errorf("path %q: no key %q to delete", p, last)
		}
		delete(m, last)
	}
	return json.Marshal(root)
}

func api100cDel(t *testing.T, raw string, paths ...string) []byte {
	t.Helper()
	b, err := api100cDelE(raw, paths...)
	require.NoError(t, err)
	return b
}

// api100cSub returns the JSON value at a dotted path of b ("" is b itself).
func api100cSub(t *testing.T, b []byte, path string) []byte {
	t.Helper()
	if path == "" {
		return b
	}
	var m map[string]json.RawMessage
	for _, k := range strings.Split(path, ".") {
		require.NoError(t, json.Unmarshal(b, &m))
		v, ok := m[k]
		require.True(t, ok, "no key %q", k)
		b = v
	}
	return b
}

