type api100cRow struct {
	name   string
	raw    string
	msg    bool     // the fixture is a whole message (else a bare poll)
	del    []string // legacy thumb keys deleted before the strict decode (paths in raw)
	want   any      // tg.Message or tg.Poll
	keys   []string // T-tg-8: new poll keys compared after encoding
	keyRel string   // path of the poll inside raw ("poll" for a message)
}

