func api100cDecode(t *testing.T, b []byte, msg, strict bool) any {
	t.Helper()
	if msg {
		var m tg.Message
		if strict {
			require.NoError(t, api96Strict(t, b, &m))
		} else {
			require.NoError(t, json.Unmarshal(b, &m))
		}
		return m
	}
	var p tg.Poll
	if strict {
		require.NoError(t, api96Strict(t, b, &p))
	} else {
		require.NoError(t, json.Unmarshal(b, &p))
	}
	return p
}

// T-tg-1 … T-tg-6: every real reply decodes into one whole expected value, and strictly after the named thumb
// deletes only.
func TestAPI100C_DecodeProbe(t *testing.T) {
	for _, r := range api100cRows() {
		t.Run(r.name, func(t *testing.T) {
			assert.Equal(t, r.want, api100cDecode(t, []byte(r.raw), r.msg, false))
			assert.Equal(t, r.want, api100cDecode(t, api100cDel(t, r.raw, r.del...), r.msg, true))
		})
	}
}

