func TestAPI100C_DecodeChannelShape(t *testing.T) {
	want := tg.Poll{ID: "poll-ch", Question: "probe100c one option", Options: []tg.PollOption{{Text: "only",
		PersistentID: "0", Media: &tg.PollMedia{Animation: &tg.Animation{FileID: "ANI-file", FileUniqueID: "ANI-uniq",
			Width: 320, Height: 240, Duration: 2, FileName: "a.mp4", MimeType: "video/mp4", FileSize: 1200}}}},
		Type: "regular", AllowsRevoting: true, MembersOnly: true, CountryCodes: []string{"DE", "FT"}}
	assert.Equal(t, want, api100cDecode(t, []byte(api100cChannel), false, false))
	assert.Equal(t, want, api100cDecode(t, []byte(api100cChannel), false, true))
}

// T-tg-8: encoding the decoded value gives the new keys with their exact names and values. Both sides select the
// same new keys: the encoded value and the fixture after the same checked thumb deletes (T2-01, T3-01).
func TestAPI100C_EncodeKeys(t *testing.T) {
	rows := append(api100cRows(), api100cRow{name: "channel", raw: api100cChannel,
		keys: []string{"members_only", "country_codes", "options"}})
	for _, r := range rows {
		t.Run(r.name, func(t *testing.T) {
			v := api100cDecode(t, []byte(r.raw), r.msg, false)
			poll := v
			if m, ok := v.(tg.Message); ok {
				require.NotNil(t, m.Poll)
				poll = *m.Poll
			}
			got, err := json.Marshal(poll)
			require.NoError(t, err)
			want := api100cSub(t, api100cDel(t, r.raw, r.del...), r.keyRel)
			assert.JSONEq(t, api100Keys(t, want, r.keys...), api100Keys(t, got, r.keys...))
		})
	}
}

// T-tg-9: zero values: Poll gains only "members_only":false; PollOption and PollMedia add nothing.
func TestAPI100C_EncodeZero(t *testing.T) {
	rows := []struct {
		name string
		v    any
		want string
	}{
		{"Poll", tg.Poll{}, `{"id":"","question":"","options":null,"total_voter_count":0,"is_closed":false,` +
			`"is_anonymous":false,"type":"","allows_multiple_answers":false,"allows_revoting":false,"members_only":false}`},
		{"PollOption", tg.PollOption{}, `{"text":"","voter_count":0,"persistent_id":""}`},
		{"PollMedia", tg.PollMedia{}, `{}`},
	}
	for _, r := range rows {
		t.Run(r.name, func(t *testing.T) {
			b, err := json.Marshal(r.v)
			require.NoError(t, err)
			assert.JSONEq(t, r.want, string(b))
		})
	}
}

// T-tg-11: the delete helper reports an absent path and deletes only the named key.
func TestAPI100C_DelHelper(t *testing.T) {
	_, err := api100cDelE(api100cProbe17, "media.video.thumbx")
	require.Error(t, err)
	_, err = api100cDelE(api100cProbe17, "media.audio.thumb")
	require.Error(t, err)
	_, err = api100cDelE(api100cProbe21, "poll.options.9.media.video.thumb")
	require.Error(t, err)

	got, err := api100cDelE(api100cProbe17, "media.video.thumb")
	require.NoError(t, err)
	var a, b map[string]any
	require.NoError(t, json.Unmarshal([]byte(api100cProbe17), &a))
	require.NoError(t, json.Unmarshal(got, &b))
	video := a["media"].(map[string]any)["video"].(map[string]any)
	require.Contains(t, video, "thumb")
	delete(video, "thumb")
	assert.Equal(t, a, b)
}
